+
+    main {
+      min-height: 100vh;
+      display: grid;
+      place-items: center;
+      padding: 2rem 1rem;
+    }
+
+    .card {
+      width: min(100%, 29rem);
+      padding: 2rem;
+      border: 1px solid var(--border);
