+      background: linear-gradient(180deg, var(--panel), var(--panel-2));
+      box-shadow: 0 20px 50px var(--shadow);
+    }
+
+    h1 {
+      margin: 0 0 0.75rem;
+      font-size: clamp(1.75rem, 3vw, 2.25rem);
+      line-height: 1.1;
+    }
+
+    .lede {
+      margin: 0 0 1.5rem;
+      color: var(--muted);
+      line-height: 1.55;
+    }
+
+    form {
+      display: grid;
+      gap: 1.25rem;
+    }
+
+    .form-field {
+      padding: 1rem;
+      border: 1px solid var(--border);
+      border-radius: 1rem;
+      background: #0f1727;
+    }
+
+    .checkbox-label {
+      display: grid;
+      grid-template-columns: 1.125rem 1fr;
+      gap: 0.875rem;
+      align-items: start;
+      cursor: pointer;
+      color: var(--text);
+      font-weight: 600;
+      line-height: 1.45;
+    }
+
+    .checkbox-label input {
+      width: 1.125rem;
+      height: 1.125rem;
+      margin: 0.2rem 0 0;
+      accent-color: var(--accent);
+    }
+
+    .required {
+      color: var(--accent-strong);
+      font-weight: 700;
+    }
+
+    .help-text {
+      margin: 0.65rem 0 0 2rem;
+      color: var(--muted);
+      font-size: 0.95rem;
+      line-height: 1.45;
+    }
+
+    .error-text {
+      margin: 0.5rem 0 0 2rem;
+      color: var(--error);
+      font-size: 0.95rem;
+      line-height: 1.45;
+      min-height: 1.45em;
+    }
+
+    button {
+      border: 1px solid #5670a6;
+      border-radius: 0.9rem;
+      padding: 0.9rem 1.15rem;
+      background: linear-gradient(180deg, #7ea2ff, #5f82d8);
+      color: #0b1020;
+      font: inherit;
+      font-weight: 700;
+      cursor: pointer;
+      transition: transform 0.15s ease, filter 0.15s ease;
+    }
+
+    button:hover {
+      filter: brightness(1.05);
+    }
+
+    button:active {
+      transform: translateY(1px);
+    }
+
+    :focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    [aria-invalid="true"] {
+      border-color: var(--error);
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin: 0;
+      color: var(--accent-strong);
+      font-weight: 600;
+    }
+
+    @media (forced-colors: active) {
+      * {
+        forced-color-adjust: auto;
+      }
+
+      .skip-link,
+      .card,
+      .form-field,
+      button {
+        border-color: ButtonBorder;
+        background: Canvas;
+        color: CanvasText;
+      }
+
+      .skip-link {
+        background: Highlight;
+        color: HighlightText;
+      }
+
+      :focus-visible {
+        outline-color: Highlight;
+      }
+
+      .required,
+      .help-text,
+      .error-text,
+      .status {
+        color: CanvasText;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main-content">Skip to main content</a>
+
+  <main id="main-content">
+    <section class="card" aria-labelledby="consent-heading">
+      <h1 id="consent-heading">Consent to the terms</h1>
+      <p class="lede">Please confirm that you agree before continuing.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <label class="checkbox-label" for="terms">
+            <input
+              id="terms"
+              name="terms"
+              type="checkbox"
+              required
+              aria-describedby="terms-help terms-error"
+            >
+            <span>I agree to the terms of use <span class="required" aria-hidden="true">*</span></span>
+          </label>
+          <p class="help-text" id="terms-help">You must accept the terms to submit.</p>
+          <p class="error-text" id="terms-error" aria-live="polite"></p>
+        </div>
+
+        <p class="status" id="form-status" aria-live="polite"></p>
+
+        <button type="submit">Submit</button>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('consent-form');
+    const checkbox = document.getElementById('terms');
+    const errorText = document.getElementById('terms-error');
+    const statusText = document.getElementById('form-status');
+
+    function setValidityMessage() {
+      const isValid = checkbox.checked;
+      checkbox.setAttribute('aria-invalid', String(!isValid));
+      errorText.textContent = isValid ? '' : 'Please check the box to continue.';
+      return isValid;
+    }
+
+    checkbox.addEventListener('change', setValidityMessage);
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+      statusText.textContent = '';
+
+      if (!setValidityMessage()) {
+        checkbox.focus();
+        return;
+      }
+
+      statusText.textContent = 'Consent saved.';
+    });
+  </script>
+</body>
+</html>
*** End Patch
